// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address attacker, address newOwner) public {
        vm.assume(attacker != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(attacker != c.owner());
        vm.prank(attacker);
        bool ok = true;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
